\label{theorem: equations of motion}
    Let \( \varphi \in C^1(\mathbb{R}_+; L^2(\Omega)) \), \( c_0 \in \mathbb{C} \), \( c_{2k} \in \mathbb{C}^* \) and \( \chi_{2k} \in L^2_s(\Omega^{2k}) \) for \( 1 \leq k \leq n \).
    At \( u \in \mathcal{M}_\varphi \) given by \eqref{eqn: equations of motion - ansatz u}, the Dirac--Frenkel time-dependent variational principle \eqref{eqn: equations of motion - variational principle} yields
    \begin{equation}
        \label{eqn: equations of motion}
        \left\{ \ \ 
            \begin{aligned}
                \dot{c}_{2k} &= \left\langle \begin{gathered} \varphi^{\otimes N-2k} \otimes_s \chi_{2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u \end{gathered} \right\rangle - c_{2k} (N-2k) \left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} \dot{\varphi} \end{gathered} \right\rangle,\\
                \dot{\chi}_{2k} &= \frac{1}{c_{2k}} \sqrt{\binom{N}{2k}}\, \operatorname{\mathrm{Proj}\,}_{\!\mathcal{N}^{(2k)}_\varphi(u)} \left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} - \sqrt{2k}\, \varphi \otimes_s \left\langle \begin{gathered} \dot{\varphi}(y) \end{gathered} \,\middle|\, \begin{gathered} \chi_{2k}(y, \cdot) \end{gathered} \right\rangle_y
                \ \ \text{ on }\ \Omega^{2k}, 
            \end{aligned}
        \right.\quad 0 \leq k \leq n,
    \end{equation}
    where $\operatorname{\mathrm{Proj}\,}_{\!\mathcal{N}^{(2k)}_\varphi(u)}$ is the orthogonal projection from $L^2_s(\Omega^{2k})$ onto $\mathcal{N}^{(2k)}_\varphi(u)$.

Let \( \Theta, \delta u \in \mathcal{T}_u \mathcal{M}_\varphi \), and write
    \begin{align*}
        \Theta &= \sum_{k=0}^n \left(\dot{c}_{2k} \varphi^{\otimes N-2k} \otimes_s \chi_{2k} + c_{2k} \varphi^{\otimes N-2k} \otimes_s \kappa_{2k} \right),
        &\delta u &= \sum_{k=0}^n \left( \delta c_{2k} \varphi^{\otimes N-2k} \otimes_s \chi_{2k} + c_{2k} \varphi^{\otimes N-2k} \otimes_s \delta\chi_{2k} \right),
    \end{align*}

    for some coefficients \( \dot{c}_{2k}, \delta c_{2k} \in \mathbb{C} \) and functions \( \delta \chi_{2k}, \kappa_{2k} \in \mathcal{N}^{(2k)}_\varphi(u) \), which are uniquely determined by \( \Theta \) and \( \delta u \).
    The variational principle \eqref{eqn: equations of motion - dirac frenkel variational principle} is now equivalent to
    \begin{equation}
        \label{eqn: n>1 - rewrite dirac frenkel variational principle}
        \left\{ \ \ 
            \begin{aligned}
                \left\langle \begin{gathered} \delta c_{2k} \varphi^{\otimes N-2k} \otimes_s \chi_{2k} \end{gathered} \,\middle|\, \begin{gathered} \Theta - \left( -\mathrm{i} H u - \Gamma_{\varphi,\dot\varphi}(u) \right) \end{gathered} \right\rangle &= 0\quad\ \forall \delta c_{2k} \in \mathbb{C}, \\
                \left\langle \begin{gathered} c_{2k} \varphi^{\otimes N-{2k}} \otimes_s \delta \chi_{2k} \end{gathered} \,\middle|\, \begin{gathered} \Theta - \left( -\mathrm{i} H u - \Gamma_{\varphi,\dot\varphi}(u) \right) \end{gathered} \right\rangle &= 0\quad\ \forall \delta\chi_{2k} \in \mathcal{N}^{(2k)}_\varphi(u),
            \end{aligned}
        \right.\quad 0\leq k \leq n.
    \end{equation}

    We use the definition of the symmetric tensor product, the orthogonality \eqref{eqn: bogoliubov orthogonality relation}, and the unit norm of \( \varphi \) and \( \chi_2 \) to obtain:
    \begin{equation*}
        \left\langle \begin{gathered} \varphi^{\otimes N-2k}\otimes_s \chi_{2k} \end{gathered} \,\middle|\, \begin{gathered} \varphi^{\otimes N-2j}\otimes_s \chi_{2j} \end{gathered} \right\rangle = \delta_{j,k},\quad \text{ and }\quad
        \left\langle \begin{gathered} \varphi^{\otimes N-2k} \otimes_s \chi_{2k} \end{gathered} \,\middle|\, \begin{gathered} \varphi^{\otimes N-2j} \otimes_s \delta\chi_{2j} \end{gathered} \right\rangle = 0,\quad 0 \leq j,k \leq n.
    \end{equation*}

    The system \eqref{eqn: n>1 - rewrite dirac frenkel variational principle} implies
    \begin{equation}
        \left\{ \ \ 
            \begin{aligned}
                \dot{c}_{2k} &= \left\langle \begin{gathered} \varphi^{\otimes N-2k} \otimes_s \chi_{2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u - \Gamma_{\varphi,\dot\varphi}(u) \end{gathered} \right\rangle, \\
                c_{2k} \kappa_{2k} &= \sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u - \Gamma_{\varphi,\dot\varphi}(u) \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \quad \text{ on } \Omega^{2k},
            \end{aligned}
        \right.\quad 0\leq k \leq n.
    \end{equation}

    Direct computations give
    \begin{equation*}
        \left\langle \begin{gathered} \varphi^{\otimes N-2j} \otimes_s \chi_{2j} \end{gathered} \,\middle|\, \begin{gathered} \Gamma_{\varphi, \dot{\varphi}} \end{gathered} \right\rangle = c_{2j} (N-2j) \left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} \dot{\varphi} \end{gathered} \right\rangle
        \quad\text{ and }\quad
        \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} \Gamma_{\varphi, \dot{\varphi}} \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} = 0.
    \end{equation*}

    We finally get
    \begin{equation*}
        \left\{ \ \ 
            \begin{aligned}
                \dot{c}_{2k} &= \left\langle \begin{gathered} \varphi^{\otimes N-2k} \otimes_s \chi_{2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u \end{gathered} \right\rangle -  c_{2k}(N-2k) \left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} \dot{\varphi} \end{gathered} \right\rangle, \\
                \kappa_{2k} &= \frac{1}{c_{2k}}  \sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \quad \text{ on } \Omega^{2k},
            \end{aligned}
        \right.\quad 0 \leq k \leq n,
    \end{equation*}

    and the result follows from \( \dot{\chi}_{2k} = \kappa_{2k} - \sqrt{2k} \varphi \otimes_s \left\langle \begin{gathered} \dot{\varphi} \end{gathered} \,\middle|\, \begin{gathered} \chi_{2k}(y, \cdot) \end{gathered} \right\rangle_y \).

\label{lemma: equations of motion angles}
    Assume \eqref{eqn: Bogoliubov tensorization}-\eqref{eqn: Bogoliubov tensorization normalized} hold.
    The angles \( \theta_{2j} \) that enforce the orthogonalities \( \left\langle \begin{gathered} \chi_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\chi}_{2j} \end{gathered} \right\rangle = 0 \) are solutions to the following differential equation:
    \begin{equation}
        \label{eqn: equations of motion angles}
        \dot{\theta}_{2j} = \frac{\mathrm{Im} \left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\widetilde{\chi}_{2j}} \end{gathered} \right\rangle}{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle}
            = \frac{(2j)!}{2^j (j-1)!} \frac{\mathrm{Im}\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\chi}_2 \otimes \chi_2^{\otimes j-1} \end{gathered} \right\rangle}{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle}, \quad j\geq1.
    \end{equation}

The orthogonality \( \left\langle \begin{gathered} \chi_2 \end{gathered} \,\middle|\, \begin{gathered} \dot{\chi}_2 \end{gathered} \right\rangle = 0 \) is already satisfied by the equation of motion for \( \chi_2 \) given in \eqref{eqn: equations of motion}.
    For \( j>1 \), we have,
        \begin{equation*}
        \dot{\chi}_{2j}
        = -\mathrm{i} \dot{\theta}_{2j} \chi_{2j} -\frac{e^{-\mathrm{i}\theta_{2j}}}{2} \frac{\frac{\partial}{\partial t} \left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle}{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle^{3/2}} \widetilde{\chi}_{2j} + \frac{e^{-\mathrm{i}\theta_{2j}} \dot{\widetilde{\chi}_{2j}}}{\sqrt{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle}}
        = -\mathrm{i}\dot{\theta}_{2j} \chi_{2j} + e^{-\mathrm{i}\theta_{2j}} \left(\frac{\dot{\widetilde{\chi}_{2j}}}{\sqrt{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle}} - \frac{\mathrm{Re}\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\widetilde{\chi}_{2j}} \end{gathered} \right\rangle}{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle^{3/2}} \widetilde{\chi}_{2j} \right),
    \end{equation*}

    and hence
    \begin{equation*}
        \left\langle \begin{gathered} \chi_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\chi}_{2j} \end{gathered} \right\rangle
        = -\mathrm{i} \dot{\theta}_{2j} - \frac{\mathrm{Re}\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\widetilde{\chi}_{2j}} \end{gathered} \right\rangle}{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle} + \frac{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\widetilde{\chi}_{2j}} \end{gathered} \right\rangle}{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle}
        = -\mathrm{i}\dot{\theta}_{2j} + \mathrm{i} \frac{\mathrm{Im}\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\widetilde{\chi}_{2j}} \end{gathered} \right\rangle}{\left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \right\rangle} \in \mathrm{i} \mathbb{R}.
    \end{equation*}

    The differential equation for \( \theta_{2j} \) is obtained by imposing the condition \( \left\langle \begin{gathered} \chi_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\chi}_{2j} \end{gathered} \right\rangle = 0 \).
    Now use \eqref{eqn: Bogoliubov tensorization}:
    \begin{equation*}
        \left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\widetilde{\chi}_{2j}} \end{gathered} \right\rangle
        = \sum_{\tau\in P_{2j}} \left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \sum_{k=1}^j (\chi_2^{\otimes k-1} \otimes \dot{\chi}_2 \otimes \chi_2^{\otimes j-k})(x_\tau) \end{gathered} \right\rangle
        = j \sum_{\tau\in P_{2j}} \left\langle \begin{gathered} \widetilde{\chi}_{2j} \end{gathered} \,\middle|\, \begin{gathered} \dot{\chi}_2 \otimes \chi_2^{\otimes j-1} \end{gathered} \right\rangle,
    \end{equation*}

    where the last equality is obtained using the symmetry of \( \widetilde{\chi}_{2j} \), and we conclude using that \( |P_{2j}|\left.\vphantom{T_{j_0}^0}\!\!\right. = \frac{(2j)!}{2^j j!} \).

\label{theorem: setting n>1 no tensorization - chi2dot uniformly bounded wrt N}
    Let \( c_0 \in \mathbb{C} \), \( c_2, \dots, c_{2n} \in \mathbb{C}^* \), \( \varphi, \phi \in L^2(\Omega) \), and \( \chi_{2k} \in L^2_s(\Omega^{2k}) \) such that
    \begin{equation*}
        \left\langle \begin{gathered} \varphi(y) \end{gathered} \,\middle|\, \begin{gathered} \chi_{2k}(y, \cdot) \end{gathered} \right\rangle_y = 0, \quad 1 \leq k \leq n.
    \end{equation*}

    Define \( u \) via \eqref{eqn: final ansatz u}, then for all \( 1 \leq k \leq n \), the quantity
    \begin{equation*}
        \frac{1}{c_{2k}} \sqrt{\binom{N}{2k}}\, \operatorname{\mathrm{Proj}\,}_{\!\mathcal{N}^{(2k)}_\varphi(u)} \left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} - \sqrt{2k} \varphi \otimes_s \left\langle \begin{gathered} \phi(y) \end{gathered} \,\middle|\, \begin{gathered} \chi_{2k}(y, \cdot) \end{gathered} \right\rangle_y
    \end{equation*}

    is uniformly bounded with respect to \( N \).

\label{lemma: reducing number of effective kinetic operators}
    Define integers \( m\in \left[0:N\right] \), \( p\in \left[0:\frac{N-m}{2} \right] \), and let \( \varphi \in L^2(\Omega) \), \( \chi_{2p} \in L_s^2(\Omega^{2p}) \) and \( w \in L^2_s(\Omega^N) \).
    Then,
    \begin{equation}
        \label{eqn: use symmetry of u to simplify the computation of braket with Delta u on the rhs}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}
        = \begin{aligned}[t]
            &\sum_{1 \leq k \leq m} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
            &\quad+ (N-m-2p) \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{m+1}} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
            &\quad+ 2p \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{N-2p+1}} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
        \end{aligned}
    \end{equation}

We have 
    \begin{align}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}
        &= \sum_{1\leq k \leq N} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \nonumber  \\
        &= \begin{aligned}[t]
            &\sum_{1\leq k \leq m} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
            &\quad+ \sum_{m+1 \leq k \leq N-2p} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
            &\quad+ \sum_{N-2p+1 \leq k} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
        \end{aligned}
        \label{eqn: proof reduction nb operators laplacian - expansion total sum}
    \end{align}

    For any \( k\in \left[m+1:N-2p\right] \), by symmetry of \( w \)
    \begin{equation*}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}
        = \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x_1, \dots, x_{k}, \dots, x_{m+1}, \dots, x_N) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
    \end{equation*}

    Only the variables \( x_k \) and \( x_{m+1} \) have been exchanged.
    Due to the symmetry of \( \varphi^{\otimes N-m-2p}(x_{m+1}, \dots, x_{N-2p}) \), we perform a change of variables \( x_k \leftrightarrow x_{m+1} \) and obtain
    \begin{equation*}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_k} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}
        = \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{m+1}} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
    \end{equation*}

    Note that the right-hand side does not depend on \( k \) anymore, thus the second sum in \eqref{eqn: proof reduction nb operators laplacian - expansion total sum} simplifies to 
    \begin{equation*}
        (N-m-2p) \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{m+1}} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
    \end{equation*}

    For the third sum in \eqref{eqn: proof reduction nb operators laplacian - expansion total sum}, we use the same arguments: for \( k\in \left[N-2p+1:N\right] \), the symmetry of \( w \) gives us
    \begin{equation*}
        w(x) = w(x_1, \dots, x_{N-2p+1}, \dots, x_k, \dots, x_N) = w(x_1, \dots, x_k, \dots, x_{N-2p+1}, \dots, x_N),
    \end{equation*}

    where only the variables \( x_k \) and \( x_{N-2p+1} \) have been exchanged.
    The symmetry of \( \chi_{2p} \) allows us to perform the change of variables \( x_k \leftrightarrow x_{N-2p+1} \), and the kinetic operator is now on variable \( x_{N-2p+1} \).
    Finally, the third sum in \eqref{eqn: proof reduction nb operators laplacian - expansion total sum} simplifies to 
    \begin{equation*}
        2p \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{N-2p+1}} w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
    \end{equation*}

\label{lemma: reducing number of effective potential operators}
    Define integers \( m\in \left[0:N\right] \), \( p\in \left[0:\frac{N-m}{2} \right] \), and let \( \varphi \in L^2(\Omega) \), \( \chi_{2p} \in L_s^2(\Omega^{2p}) \) and \( w \in L^2_s(\Omega^N) \).
    Then,
    \begin{multline*}
        \label{eqn: use symmetry of u to simplify the computation of braket with Vu on the rhs}
            (N-1)\left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} Vw(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
            = \begin{aligned}[t]
                &\sum_{1 \leq k < l \leq m} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_{k} - x_{l}) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
                &\quad+ (N-m-2p) \sum_{k=1}^m \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_k - x_{m+1}) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
                &\quad + 2p \sum_{k=1}^m \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_k - x_{N-2p+1}) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
                &\quad+ \frac{(N-m-2p-1)(N-m-2p)}{2} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_{m+1} - x_{m+2}) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
                &\quad+ 2p(N-m-2p) \left\langle \begin{gathered} \varphi^{\otimes N-m-{2p}} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_{m+1} - x_{N-2p+1}) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
                &\quad+ \frac{2p(2p-1)}{2} \left\langle \begin{gathered} \varphi^{\otimes N-m-{2p}} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_{N-2p+1} - x_{N-2p+2}) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
            \end{aligned}
    \end{multline*}

The proof is very similar to the proof of Lemma \ref{lemma: reducing number of effective kinetic operators}, we just need to deal with a two-body operator instead of a one-body operator.
    We have
    \begin{equation}
        \begin{aligned}
            (N-1)\left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} Vw(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}
            &=\sum_{k=1}^m \sum_{l=k+1}^m \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_k - x_l) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
            &\quad+ \sum_{k=1}^m \sum_{l=m+1}^N \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_k - x_l) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
            &\quad+ \sum_{k=m+1}^{N-1} \sum_{l=k+1}^N \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} v(x_k - x_l) w(x) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}.
        \end{aligned}
        \label{eqn: use symmetry of u to simplify the computation of braket with V on the rhs - split sums over k and l}
    \end{equation}

    We distinguish the following situations:
    \begin{itemize}
        \item \( k \in \left[1:m\right], l\in \left[m+1:N-2p\right] \)
        \item \( k \in \left[1:m\right], l\in \left[N-2p+1:N\right] \)
        \item \( k \in \left[m+1:N-2p\right], l\in \left[k+1:N-2p\right] \)
        \item \( k \in \left[m+1:N-2p\right], l\in \left[N-2p+1:N\right] \)
        \item \( k \in \left[N-2p+1:N\right], l\in \left[k+1:N\right] \),
    \end{itemize}
    and for each of them the same arguments as before can be used.

The functions \( \varphi, \phi \) and \( \chi_{2k} \) are of unit norm, therefore the quantity \( \sqrt{2k} \varphi \otimes_s \left\langle \begin{gathered} \phi \end{gathered} \,\middle|\, \begin{gathered} \chi_{2k}(y, \cdot) \end{gathered} \right\rangle_y \) is uniformly bounded with respect to \( N \).

    We now need to show that \( \frac{1}{c_{2k}} \sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\mathrm{i} H u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \) is uniformly bounded with respect to \( N \).
    By Lemmas \ref{lemma: reducing number of effective kinetic operators} and \ref{lemma: reducing number of effective potential operators}, it is sufficient to show that it is the case for the following quantities:
    \begin{enumerate}[label=(\alph{*})]
        \item \( \sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_i} u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \), \( i=1, \dots, 2k \).

        \item \( (N-2k)\sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{2k+1}} u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \).

        \item \( \frac{\sqrt{\binom{N}{2k}}}{N-1} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{i_1} - x_{i_2}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \), \( 1 \leq i_1 < i_2 \leq 2k \).

        \item \( \frac{\sqrt{\binom{N}{2k}}}{N-1} (N-2k) \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_i - x_{2k+1}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \), \( 1 \leq i \leq 2k \).

        \item \( \frac{\sqrt{\binom{N}{2k}}}{N-1} \frac{(N-2k)(N-2k-1)}{2} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{2k+1} - x_{2k+2}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \).
    \end{enumerate}

    In what follows, we will use the orthogonality \eqref{eqn: bogoliubov orthogonality relation}, the symmetry of all excitation functions \( \chi_{2j} \), and the fact that the orthogonal projection onto \( \mathcal{N}^{(2k)}_\varphi(u) \) eliminates all multiples of \( \chi_{2k} \) as well as all functions of \( 2k \) variables with a marginal that is a multiple of \( \varphi \).
    These arguments will be used many times throughout this proof. We gather them here to avoid repeating them every time they are used.

    For the term (a), with \( 1 \leq i \leq 2k \), we have
    \begin{multline*}
        \sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_i} u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\
        = \sqrt{\binom{N}{2k}} \sum_{j=0}^n c_{2j} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_i} (\varphi^{\otimes N-2j} \otimes_s \chi_{2j}) \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}}.
    \end{multline*}

    The right-hand side has a vanishing summand for \( j\neq k \), hence
    \begin{align*}
        \sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_i} u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} 


        &= c_{2k} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} (-\Delta_{x_i} \chi_{2k})
    \end{align*}

    is uniformly bounded with respect to \( N \). 
    For the term (b), we have
    \begin{multline*}
        (N-2k)\sqrt{\binom{N}{2k}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{2k+1}} u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\
        = (N-2k)\sqrt{\binom{N}{2k}} \sum_{j=0}^n c_{2j} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_{2k+1}} \varphi^{\otimes N-2j} \otimes_s \chi_{2j} \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}}
    \end{multline*}

    All summands vanish.
    For the term (c), with \( 1 \leq i_1 < i_2 \leq 2k \), we have
    \begin{multline}
        \frac{\sqrt{\binom{N}{2k}}}{N-1} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{i_1} - x_{i_2}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\
        = \frac{\sqrt{\binom{N}{2k}}}{N-1} \sum_{j=0}^n c_{2j} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{i_1} - x_{i_2}) \varphi^{\otimes N-2j}\otimes_s \chi_{2j} \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}}.
    \end{multline}

    The right-hand side has a vanishing summand for \( j<k-1 \) and \( j>k \).
    With \( j=k-1 \), we get
    \begin{multline*}
        \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{i_1} - x_{i_2}) \varphi^{\otimes N-2k+2}\otimes_s \chi_{2k-2} \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\

        = \frac{1}{\sqrt{\binom{N}{2k-2}}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left( v(x_{i_1}-x_{i_2}) \varphi(x_{i_1}) \varphi(x_{i_2}) \chi_{2k-2}(x_{\left[1:2k\right]\setminus \{i_1, i_2\}}) \right).
    \end{multline*}

    With \( j=k \), we get
    \begin{align*}
        \left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{i_1} - x_{i_2}) \varphi^{\otimes N-2k}\otimes_s \chi_{2k} \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}}

        &= \frac{1}{\sqrt{\binom{N}{2k}}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left( v(x_{i_1} - x_{i_2}) \chi_{2k}(x_{\left[1:2k\right]}) \right).
    \end{align*}

    Thus, 
    \begin{multline*}
        \frac{\sqrt{\binom{N}{2k}}}{N-1} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{i_1} - x_{i_2}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\
        = \frac{\sqrt{\binom{N}{2k}}}{(N-1)\sqrt{\binom{N}{2k-2}}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left( v(x_{i_1}-x_{i_2}) \varphi(x_{i_1}) \varphi(x_{i_2}) \chi_{2k-2}(x_{\left[1:2k\right]\setminus \{i_1, i_2\}}) \right) \\
        + \frac{\sqrt{\binom{N}{2k}}}{(N-1)\sqrt{\binom{N}{2k}}} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left( v(x_{i_1} - x_{i_2}) \chi_{2k}(x_{\left[1:2k\right]}) \right),
    \end{multline*}

    and the right-hand side is uniformly bounded with respect to \( N \).
    For the term (d), with \( 1 \leq i \leq 2k \), we have
    \begin{multline*}
        \frac{\sqrt{\binom{N}{2k}}}{N-1} (N-2k) \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_i - x_{2k+1}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\
        = \frac{\sqrt{\binom{N}{2k}}}{N-1} (N-2k) \sum_{j=0}^n c_{2j} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_i - x_{2k+1}) \varphi^{\otimes N-2j} \otimes_s \chi_{2j} \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}}.
    \end{multline*}

    The right-hand side has a vanishing summand for \( j\neq k \), hence
    \begin{multline*}
        \frac{\sqrt{\binom{N}{2k}}}{N-1} (N-2k) \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_i - x_{2k+1}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\





        = \frac{N-2k}{N-1} c_{2k} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)} \left( \begin{gathered}
            \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} v(x_i - x_{2k+1}) \varphi(x_{2k+1}) \chi_{2k}(x_{\left[1:2k\right]}) \end{gathered} \right\rangle_{x_{2k+1}} \\
            + \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} v(x_i - x_{2k+1}) \varphi(x_i) \chi_{2k}(x_{\left[1:2k+1\right]\setminus\{i\}}) \end{gathered} \right\rangle_{x_{2k+1}}
        \end{gathered} \right),
    \end{multline*}

    which is uniformly bounded with respect to \( N \).
    For the term (e), we have
    \begin{multline*}
        \frac{\sqrt{\binom{N}{2k}}}{N-1} \frac{(N-2k)(N-2k-1)}{2} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{2k+1} - x_{2k+2}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\
        = \frac{\sqrt{\binom{N}{2k}}}{N-1} \frac{(N-2k)(N-2k-1)}{2} \sum_{j=0}^n c_{2j} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{2k+1} - x_{2k+2}) \varphi^{\otimes N-2j} \otimes_s \chi_{2j} \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}}.
    \end{multline*}

    The right-hand side has a vanishing summand for \( j\neq k+1 \).
    Hence,
    \begin{multline*}
        \frac{\sqrt{\binom{N}{2k}}}{N-1} \frac{(N-2k)(N-2k-1)}{2} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes N-2k} \end{gathered} \,\middle|\, \begin{gathered} v(x_{2k+1} - x_{2k+2}) u \end{gathered} \right\rangle_{x_{\left[2k+1:N\right]}} \\


        = \frac{\sqrt{\binom{N}{2k}}}{N-1} \frac{(N-2k)(N-2k-1)}{2} \frac{1}{\sqrt{\binom{N}{2k+2}}} c_{2k+2} \operatorname{\mathrm{Proj}\,}_{\mathcal{N}^{(2k)}_\varphi(u)}\left\langle \begin{gathered} \varphi^{\otimes 2} \end{gathered} \,\middle|\, \begin{gathered} v(x_{2k+1} - x_{2k+2}) \chi_{2k+2} \end{gathered} \right\rangle_{x_{\{2k+1, 2k+2\}}},
    \end{multline*}

    which is uniformly bounded with respect to \( N \).

\label{theorem: unitary evolution coeffs}
    Assume \( \varphi \) is solution to the Hartree equation \eqref{eqn: hartree equation}.
    Then, for all times \( t \), the entries of the Hermitian matrix \( \check{\mathbf{H}}(t) \) are slowly varying with respect to time and uniformly bounded with respect to \( N \).

The matrix \( \check{\mathbf{H}} \) is Hermitian since \( \mathbf{H} \) is Hermitian and \( \left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} \mathrm{i}\dot{\varphi} \end{gathered} \right\rangle \in \mathbb{R} \).
    For \( 0 \leq j \leq n \), explicit computations give (details in Appendix \ref{appendix: components bfH}):
    \begin{equation*}
        \mathbf{H}_{j,j} 
        = \begin{aligned}[t]
            &\frac{(N-2j)(N-2j-1)}{2(N-1)} \left\langle \begin{gathered} \varphi^{\otimes 2} \end{gathered} \,\middle|\, \begin{gathered} v(x_1-x_2) \varphi^{\otimes 2} \end{gathered} \right\rangle + \frac{2j(2j-1)}{2(N-1)} \left\langle \begin{gathered} \chi_{2j} \end{gathered} \,\middle|\, \begin{gathered} v(x_1-x_2) \chi_{2j} \end{gathered} \right\rangle \\
            &+\frac{2j(N-2j)}{N-1} \Big( \left\langle \begin{gathered} \chi_{2j} \otimes \varphi \end{gathered} \,\middle|\, \begin{gathered} v(x_1-x_{2j+1}) \varphi \otimes \chi_{2j} \end{gathered} \right\rangle + \left\langle \begin{gathered} \chi_{2j} \otimes \varphi \end{gathered} \,\middle|\, \begin{gathered} v(x_1 - x_{2j+1}) \chi_{2j} \otimes \varphi \end{gathered} \right\rangle \Big) \\
            &+ (N-2j) \left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} -\Delta \varphi \end{gathered} \right\rangle + 2j \left\langle \begin{gathered} \chi_{2j} \end{gathered} \,\middle|\, \begin{gathered} -\Delta_{x_1}\chi_{2j} \end{gathered} \right\rangle.
        \end{aligned}
    \end{equation*}

    All the brakets in \( \mathbf{H}_{j,j} \) are uniformly bounded with respect to \( N \), thus we can write \( \mathbf{H}_{j,j} = \beta_1 N + \beta_2 + \beta_3 / N \) for some coefficients \( \beta_1, \beta_2, \beta_3 \in \mathbb{R} \) that are independent of \( N \).
    More precisely, we have
    \begin{equation*}
        \mathbf{H}_{j,j} = N \left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} -\Delta\varphi \end{gathered} \right\rangle + \frac{N}{2} \left\langle \begin{gathered} \varphi^{\otimes 2} \end{gathered} \,\middle|\, \begin{gathered} v(x_1-x_2) \varphi^{\otimes 2} \end{gathered} \right\rangle + \mathcal{O}(1), \quad 0 \leq j \leq n,
    \end{equation*}

    where \( \mathcal{O}(1) \) denotes a quantity that is uniformly bounded with respect to \( N \).
    The coefficient \( \frac{1}{2} \left\langle \begin{gathered} \varphi^{\otimes 2} \end{gathered} \,\middle|\, \begin{gathered} v(x_1-x_2) \varphi^{\otimes 2} \end{gathered} \right\rangle \) is exactly the coefficient \( \mu_{\varphi(t)} \) defined in \eqref{eqn: mu in hartree equation}.
    Since \( \varphi \) is solution to the Hartree equation \eqref{eqn: hartree equation}, we can write
    \begin{equation*}
        \mathbf{H}_{j,j} = N \left\langle \begin{gathered} \varphi \end{gathered} \,\middle|\, \begin{gathered} \mathrm{i}\dot{\varphi} \end{gathered} \right\rangle + \mathcal{O}(1).
    \end{equation*}

    Therefore, the diagonal elements of the matrix \( \check{\mathbf{H}} \) are all uniformly bounded with respect to \( N \).
    For the off-diagonal terms, we have (see again Appendix \ref{appendix: components bfH}):
    \begin{equation*}
        \overline{\mathbf{H}_{j+1, j}} = \mathbf{H}_{j,j+1}
        = \frac{\sqrt{(N-2j)(N-2j-1)}}{2(N-1)} \sqrt{(2j+2)(2j+1)} \left\langle \begin{gathered} \varphi^{\otimes 2} \otimes \chi_{2j} \end{gathered} \,\middle|\, \begin{gathered} v(x_1-x_2) \chi_{2j+2} \end{gathered} \right\rangle,\quad 0 \leq j \leq n-1,
    \end{equation*}

    which are also uniformly bounded with respect to \( N \).
    The smoothness of the matrix \( \check{\mathbf{H}} \) with respect to time is simply due to the fact that it depends only on \( \varphi \) and on the excitation functions \( \chi_{2j} \), which are smooth with respect to time by Theorem \ref{theorem: setting n>1 no tensorization - chi2dot uniformly bounded wrt N}.

\label{lemma: when does braket varphiN-m-p otimes chip vs A varphiN-j otimes chiq vanishes depending on p q s m}
    Let \( m \in \left[0:N\right] \), \( p, q \in \left[0:n\right] \), \( \tau\in S_N \), and \( A_{\ell_1, \ell_2} \) a two-body operator acting on variables \( \ell_1, \ell_2 \).
    Let \( \varphi \in L^2(\Omega) \), \( \chi_{2p} \in L^2_s(\Omega^{2p}) \) and \( \chi_{2q} \in L^2_s(\Omega^{2q}) \), such that \( \|\varphi\|\left.\vphantom{T_{j_0}^0}\!\!\right._{2} = 1 \) and the orthogonality \eqref{eqn: bogoliubov orthogonality relation} is satisfied.
    Then the braket
    \begin{equation*}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} A_{\ell_1, \ell_2} \varphi^{\otimes N-2q}(x_{\tau(\left[2q+1:N\right])})\chi_{2q}(x_{\tau(\left[1:2q\right])}) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}}
    \end{equation*}

    vanishes when
    \begin{equation}
        2p > 2q+2 \quad \text{or}\quad 2q > 2p+m+2.
    \end{equation}

\label{lemma: symmetric tensor product rewritten with only unique permutations}
    Let \( i,j \geq 1 \), and \( f \in L^2_s(\Omega^i) \), \( g\in L^2_s(\Omega^j) \).
    Then
    \begin{equation}
        \label{eqn: symmetric tensor product rewritten with only unique permutations}
        (f\otimes_s g)(x) = \binom{i+j}{j}^{-1/2} \sum_{\substack{\tau \in S^{j}_{i+j}\\\tau\,\mathrm{sorted}}} f(x \setminus x_\tau) g(x_{\tau}),
    \end{equation}

    where ``\( \tau \in S^j_{i+j} \) is sorted'' means that \( \tau \) is sorted according to a given total ordering.

\label{def: valid permutation tau}
    For given \( N, p, q, \ell_1, \ell_2 \), a permutation \( \tau \in S^{2q}_{\mathcal{T}^C} \) is said to be \emph{valid} if \( \left[N-2p+1:N\right] \subset \{\ell_1, \ell_2\}\cup \tau \).
    In other words, a permutation \( \tau \in S^{2q}_{\mathcal{T}^C} \) is valid if the braket \( \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} \varphi^{\otimes N-2q}(x \setminus x_\tau) \chi_{2q}(x_{\tau}) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \) doesn't involve any one-dimensional braket of the form \( \left\langle \begin{gathered} \chi_{2p}(y, \cdot) \end{gathered} \,\middle|\, \begin{gathered} \varphi(y) \end{gathered} \right\rangle_y \).

\label{lemma: sum over tau in Sjn with no braket along phi}
    Let integers \( m \in \left[0:N\right] \), \( p, q \in \left[0:n\right] \).
    Let functions \( \varphi \in L^2(\Omega) \), \( \chi_{2p} \in L^2_s(\Omega^{2p}) \) and \( \chi_{2q} \in L^2_s(\Omega^{2q}) \), such that \( \|\varphi\|\left.\vphantom{T_{j_0}^0}\!\!\right._{2} = 1 \) and the orthogonality \eqref{eqn: bogoliubov orthogonality relation} is satisfied.
    For any \( \ell_1, \ell_2 \in \left[1:N\right] \),
    \begin{multline}
        \label{eqn: sum over tau in Sjn with no braket along phi}
        \sum_{\substack{\tau\in S^{2q}_N\\\tau\,\mathrm{sorted}}} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2}\varphi^{\otimes N-2q}(x\setminus x_\tau) \chi_{2q}(x_\tau) \end{gathered} \right\rangle_{x_{\left[m+1:N\right]}} \\
        = \sum_{\substack{\tau\in S^{2q}_{\mathcal{T}^C}\\\tau\,\mathrm{sorted,\,valid}}} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p}  \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} \varphi^{\otimes N-2q}(x\setminus x_\tau) \chi_{2q}(x_\tau) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}}.
    \end{multline}

\label{lemma: operator splitting - potential hartree equation with phi0}
    Let \( \varphi \) be the solution to \eqref{eqn: operator splitting - potential hartree equation} with initial condition \( \varphi_0 \).
    Then, for all \( x\in \Omega \) and all times \( t\geq 0 \),
    \begin{equation}
        \label{eqn: operator splitting - potential hartree equation with phi0}
        \mathrm{i} \dot{\varphi}(t) = (v\ast |\varphi_0|\left.\vphantom{T_{j_0}^0}\!\!\right.^2 - \mu_{\varphi_0}) \varphi(t).
    \end{equation}

\label{lemma: get rid of all one-dimensional brakets of the form phi-phi}
    Let \( p,q\in \left[0:n\right] \) and \( \tau \in S^{2q}_{\mathcal{T}^C} \) a valid sorted permutation.
    We have
    \begin{multline}
        \label{eqn: simplification braket potential part with multiindices calQ and calP}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \chi_{2q}(x_\tau) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}} \\
        = \sum_{i'_{\mathcal{P}^C}=1}^r \sum_{i_{\mathcal{Q}^C}=1}^r \left\langle \begin{gathered} \varphi^{\otimes N-m-2p}\otimes \\  \eta_{i'_1} \otimes \dots \otimes \eta_{i'_{2p}} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2}\left( \begin{gathered} \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \\ (\eta_{i_1} \otimes \dots \otimes \eta_{i_{2q}})(x_\tau) \end{gathered} \right) \end{gathered} \right\rangle_{\substack{x_{\{\ell_1, \ell_2\}\setminus\left[1:m\right]}\\\mathbf{1}_{\left[m+1:N\right]\setminus\{\ell_1, \ell_2\}}}}
            \sum_{i'_{\mathcal{P}}=1}^r \overline{b_{i'_{\mathcal{P}}, i'_{\mathcal{P}^C}}} b_{i'_\mathcal{P}, i_{\mathcal{Q}^C}}.
    \end{multline}

We use the rank-\( r \) approximation \eqref{eqn: LRA chi2j} of \( \chi_{2p} \) and \( \chi_{2q} \):
    \begin{multline*}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2}\left( \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \chi_{2q}(x_\tau) \right) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}} \\
        = \sum_{\substack{i'_1, \dots, i'_{2p}=1\\i_1, \dots, i_{2q}=1}}^r \overline{b_{i'_1, \dots, i'_{2p}}} b_{i_1, \dots, i_{2q}} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p}\otimes \eta_{i'_1} \otimes \dots \otimes \eta_{i'_{2p}} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} \varphi^{\otimes N-2q}(x\setminus x_\tau) (\eta_{i_1} \otimes \dots \otimes \eta_{i_{2q}})(x_\tau) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}}.
    \end{multline*}

    We can write the sum over \( (i_1, \dots, i_{2q}) \) as two sums: one over the multi-index \( i_{\mathcal{Q}^C} \) and one over the multi-index \( i_{\mathcal{Q}} \):
    \begin{multline*}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \chi_{2q}(x_\tau) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}} \\
        = \sum_{i'_1, \dots, i'_{2p}=1}^r \sum_{i_{\mathcal{Q}^C}=1}^r \sum_{i_{\mathcal{Q}}=1}^r \overline{b_{i'_1, \dots, i'_{2p}}} b_{i_1, \dots, i_{2q}} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \\ \eta_{i'_1} \otimes \dots \otimes \eta_{i'_{2p}} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} 
            \left(\begin{gathered}
                \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \\
                (\eta_{i_1} \otimes \dots \otimes \eta_{i_{2q}})(x_\tau)
            \end{gathered}\right) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}}.
    \end{multline*}

    The set \( \mathcal{Q} \) is the set of indices \( k \) for which the braket along variable \( x_{\tau(k)} \) is of the form \( \left\langle \begin{gathered} \eta_{i'_{\tau(k)-N+2p}} \end{gathered} \,\middle|\, \begin{gathered} \eta_{i_k} \end{gathered} \right\rangle = \delta_{i'_{\tau(k)-N+2p}, i_k} \). 
    By definition of the set \( \mathcal{P} \), we get
    \begin{multline*}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \chi_{2q}(x_\tau) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}} \\
        = \sum_{i'_1, \dots, i'_{2p}=1}^r \sum_{i_{\mathcal{Q}^C}=1}^r \sum_{i_{\mathcal{Q}}=1}^r \overline{b_{i'_1, \dots, i'_{2p}}} b_{i_1, \dots, i_{2q}} \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \\ \eta_{i'_1} \otimes \dots \otimes \eta_{i'_{2p}} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2}\left( \begin{gathered} \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \\ (\eta_{i_1} \otimes \dots \otimes \eta_{i_{2q}})(x_\tau) \end{gathered} \right) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}\setminus \tau(\mathcal{Q})} \\ \mathbf{1}_{\mathcal{T} \cup \tau(\mathcal{Q})}}} \delta_{i'_{\mathcal{P}}, i_\mathcal{Q}}.
    \end{multline*}

    The indices \( i_1, \dots, i_{2q} \) still appear above in the arguments of the braket to simplify the notation, but the one-dimensional brakets along variables indexed by \( \tau(\mathcal{Q}) \) are known to be equal to one and thus do not need to be computed in practice.
    Moreover, the permutation \( \tau \) being valid, by Definition \ref{def: valid permutation tau} we have \( \left[N-2p+1:N\right]\setminus \{\ell_1, \ell_2\} \subset \tau \).
    It means that
    \begin{equation*}
        \forall j\in \left[N-2p+1:N\right]\setminus \{\ell_1, \ell_2\}, \exists k\in \left[1:2q\right] \quad s.t. \quad \tau(k) = j.
    \end{equation*}

    This implies \( \tau(\mathcal{Q}) = \left[N-2p+1:N\right]\setminus \{\ell_1, \ell_2\} \).
    Thus we have \( \mathcal{B}\setminus \tau(\mathcal{Q}) = \{\ell_1, \ell_2\} \setminus \left[1:m\right] \) and \( \mathcal{T} \cup \tau(\mathcal{Q}) = \left[m+1:N\right] \setminus \{\ell_1, \ell_2\} \).
    Now we do a similar decomposition on the sum over the indices \( (i'_1, \dots, i'_{2p}) \): it is a sum over the multi-index \( i'_{\mathcal{P}^C} \) and a sum over the multi-index \( i'_\mathcal{P} \).
    Then,
    \begin{multline*}
        \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \otimes \chi_{2p} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2} \varphi^{\otimes N-{2q}}(x\setminus x_{\tau}) \chi_{2q}(x_\tau) \end{gathered} \right\rangle_{\substack{x_{\mathcal{B}} \\ \mathbf{1}_{\mathcal{T}}}} \\
        = \sum_{i'_{\mathcal{P}^C}=1}^r \sum_{i_{\mathcal{Q}^C}=1}^r \left\langle \begin{gathered} \varphi^{\otimes N-m-2p} \\ \otimes \eta_{i'_1} \otimes \dots \otimes \eta_{i'_{2p}} \end{gathered} \,\middle|\, \begin{gathered} V_{\ell_1, \ell_2}\left( \begin{gathered} \varphi^{\otimes N-2q}(x\setminus x_{\tau}) \\ (\eta_{i_1} \otimes \dots \otimes \eta_{i_{2q}})(x_\tau) \end{gathered} \right) \end{gathered} \right\rangle_{\substack{x_{\{\ell_1, \ell_2\} \setminus \left[1:m\right]} \\ \mathbf{1}_{\left[m+1:N\right] \setminus \{\ell_1, \ell_2\}}}} \sum_{i'_{\mathcal{P}}=1}^r \sum_{i_{\mathcal{Q}}=1}^r \delta_{i'_\mathcal{P}, i_\mathcal{Q}} \overline{b_{i'_1, \dots, i'_{2p}}} b_{i_1, \dots, i_{2q}}.
    \end{multline*}

    Again, we have kept all the indices \( i'_1, \dots, i'_{2p} \) in the braket to simplify the notation, but only the braket along variables indexed by \( \{\ell_1, \ell_2\} \setminus \left[1:m\right] \) needs to be computed and the braket along all other variables indexed by \( \left[m+1:N\right] \setminus \{\ell_1, \ell_2\} \) is equal to one.
    We conclude using the symmetry of the core tensors.

\label{lemma: associativity symmetric tensor product}
    Let \( i, j, k \in \mathbb{N} \), and \( f \in L^2_s(\Omega^i) \), \( g \in L^2_s(\Omega^j) \), \( h \in L^2_s(\Omega^k) \).
    Then,
    \begin{equation*}
        (f \otimes_s g) \otimes_s h = f \otimes_s (g \otimes_s h).
    \end{equation*}

\label{lemma: braket hf against v rewritten as h against fv}
    Let \( i,j \in \mathbb{N} \), and \( f\in L^2(\mathbb{R}^i) \), \( g\in L^2(\mathbb{R}^{j}) \), \( h\in L^2_s(\mathbb{R}^{i+j}) \). Then,
    \begin{equation*}
        \left\langle \begin{gathered} f\otimes_s g \end{gathered} \,\middle|\, \begin{gathered} h \end{gathered} \right\rangle = \sqrt{\binom{i+j}{j}} \left\langle \begin{gathered} f \otimes g \end{gathered} \,\middle|\, \begin{gathered} h \end{gathered} \right\rangle.
    \end{equation*}

\label{lemma: symmetric tensor product of a function and itself}
    Let \( f \in L^2(\Omega) \), \( p \in \mathbb{N} \).
    Then
    \begin{equation*}
        (f^{\otimes p} \otimes_s f) = \sqrt{p+1} f^{\otimes p+1}.
    \end{equation*}

We have
    \begin{equation*}
        f^{\otimes p} \otimes_s f
        = \frac{1}{\mathsf{K}^{p+1}_1} \sum_{\sigma\in S_{p+1}} f^{\otimes p} (x_{\sigma(\left[1:p\right])}) f(x_{\sigma(p+1)})
        = \frac{(p+1)}{\mathsf{K}^{p+1}_1} f^{\otimes p+1} = \sqrt{p+1} f^{\otimes p+1}.
    \end{equation*}

\label{lemma: Derivative of k-fold tensor product}
    Let \( \varphi=\varphi(t,\cdot) \in L^2(\Omega) \) a differentiable function with respect to time \( t \), and \( k \geq 1 \).
    Then 
    \begin{equation}
        \frac{\partial}{\partial t} \left( \varphi^{\otimes k} \right) = \sqrt{k} \varphi^{\otimes k-1} \otimes_s \dot{\varphi}.
    \end{equation}

On the one hand, we have
    \begin{align*}
        \frac{\partial}{\partial t} \left( \varphi^{\otimes k} \right) 
        = \dot{\varphi}\otimes \varphi \otimes \cdots \otimes \varphi + \cdots + \varphi\otimes \cdots \varphi \otimes \dot{\varphi}
        = \sum_{j=1}^k \dot{\varphi}(x_j) \varphi^{\otimes k-1} (x\setminus x_j).
    \end{align*}

    On the other hand, 
    \begin{equation*}
        \varphi^{\otimes k-1} \otimes_s \dot{\varphi}
        = \frac{1}{\mathsf{K}^k_1} \sum_{\sigma\in S_k} \varphi^{\otimes k-1} (x_{\sigma(\left[1:k-1\right])}) \dot{\varphi}(x_{\sigma(k)})
        = \frac{1}{\sqrt{k}} \sum_{j=1}^k \dot{\varphi}(x_j) \varphi^{\otimes k-1} (x\setminus x_j),
    \end{equation*}

    which yields the result.
